---
// Embeds a self-hosted LOOPY causal-loop diagram (see public/loopy/README.md).
// `data` is a LOOPY model string: [nodes, edges, labels, UID] as JSON with
// quotes written %22, the trailing ] as %5B/%5D, and label text double-encoded.
// `embed=1` hides the editing chrome but keeps the simulation (play/pause and
// drag-a-node-to-perturb).
interface Props {
  data: string;
  height?: number;
  title?: string;
}

const { data, height = 520, title = 'Causal loop diagram' } = Astro.props;
---

<div class="overflow-hidden rounded-lg border-2 border-blue-300">
  <iframe
    src={`/loopy/v1.1/index.html?embed=1&data=${data}`}
    title={title}
    loading="lazy"
    style={`display:block;border:0;width:100%;height:${height}px`}></iframe>
</div>

